200: function tone(freq, dur = 0.14, type = 'sine', vol = 0.035, delay = 0) {
201:   if (!soundOn) return;
202:   const ctx = audio(); if (!ctx) return;
203:   const t0 = ctx.currentTime + delay;
204:   const osc = ctx.createOscillator();
205:   const g = ctx.createGain();
206:   osc.type = type; osc.frequency.setValueAtTime(freq, t0);
207:   g.gain.setValueAtTime(0, t0);
208:   g.gain.linearRampToValueAtTime(vol, t0 + 0.015);
209:   g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
210:   osc.connect(g); g.connect(ctx.destination);
211:   osc.start(t0); osc.stop(t0 + dur + 0.02);
212: }
213: function playSound(kind) {
214:   if (!soundOn) return;
215:   if (kind === 'action') { tone(392, 0.18, 'sine', 0.03); tone(587, 0.22, 'sine', 0.02, 0.05); }
216:   else if (kind === 'turn') { tone(196, 0.5, 'sine', 0.03); tone(294, 0.45, 'sine', 0.02, 0.08); tone(392, 0.4, 'sine', 0.015, 0.16); }
217:   else if (kind === 'ascend') { [261, 329, 392, 523, 659].forEach((f, i) => tone(f, 1.1, 'sine', 0.028, i * 0.12)); tone(130, 1.4, 'triangle', 0.02); }
218:   else if (kind === 'error') { tone(150, 0.16, 'square', 0.016); }
219:   else if (kind === 'click') { tone(660, 0.05, 'sine', 0.02); }
220:   else if (kind === 'omen') { tone(220, 0.6, 'triangle', 0.02); tone(330, 0.5, 'sine', 0.015, 0.15); }
221: }
