507:   }
508:   $('#hudName').textContent = state.god.name;
509:   $('#hudRank').textContent = rankName(rank);
510:   $('#hudEpithet').textContent = `${t(state.god.epithet)} · ${t(state.god.pantheon)} · ${ageLabel(age)}`;
511:   $('#hudMight').textContent = fmt(might);
