650: function bindGame() {
651:   $('#actionsGrid').addEventListener('click', e => {
652:     const card = e.target.closest('.action'); if (!card) return;
653:     const action = ACTIONS.find(a => a.id === card.dataset.action); if (!action) return;
654:     if (action.special === 'race') { openRaceForge(); return; }
655:     if (!canAfford(state, action)) {
656:       toast(missingReasonText(action) || t('The heavens are not yet ready.'), true);
657:       playSound('error');
658:       return;
659:     }
660:     const res = performAction(state, action.id);
661:     if (!res.ok) { toast(t(res.error), true); playSound('error'); return; }
662:     state.followerDelta = res.changes ? res.changes.followers || 0 : 0;
663:     addLog(state, action.glyph, res.text, toneForAction(action.id), actionChronicleText(action.id, res));
664:     renderGame();
665:     flashAction(action.id);
666:     playSound('action');
667:     const summary = res.changes ? changeTags(res.changes).slice(0, 3).join(' · ') : (res.relic ? res.relic.name : t('Done'));
